using System;
using System.IO;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
using TasiaCraft;
public static partial class MediaBinTest {
 static void SnapReject(Action action,string label){bool rejected=false;try{action();}catch(ArgumentException){rejected=true;}Check(rejected,label);}
 static void SnapTests(Editor editor,Project original,LivePreview preview){
  var p=new Project();p.Clips.Add(new Clip{Text="A",Start=1,Duration=.5,Track=0});p.Clips.Add(new Clip{Text="B",Start=3,Duration=.5,Track=1});var marker=TimelineMarkers.Add(p,5);string baseline=json.Serialize(p);
  for(int bits=0;bits<8;bits++){var options=new TimelineSnapOptions{MediaEdges=(bits&1)!=0,Playhead=(bits&2)!=0,Markers=(bits&4)!=0};var targets=TimelineSnapping.Targets(p,options,null,7,null);Check(targets.Contains(1)==options.MediaEdges&&targets.Contains(3.5)==options.MediaEdges&&targets.Contains(5)==options.Markers&&targets.Contains(7)==options.Playhead&&targets.Contains(0),"independent snapping target combination "+bits);}
  var all=new TimelineSnapOptions();p.HiddenTracks.Add(1);p.LockedTracks.Add(1);Check(TimelineSnapping.Targets(p,all,null,null,null).Contains(3),"hidden and locked clip edges remain snapping targets");p.SnapDisabledTracks.Add(1);Check(!TimelineSnapping.Targets(p,all,null,null,null).Contains(3),"target tracks with disabled snapping are excluded");Check(!TimelineSnapping.Targets(p,all,new[]{p.Clips[0].Id},null,null).Contains(1),"moving clip edges excluded by identity");Check(!TimelineSnapping.Targets(p,all,null,null,marker.Id).Contains(5),"moving marker excludes its own target");Check(!TimelineSnapping.Targets(p,all,null,null,null).Contains(7),"playhead target absent when caller omits it");p.HiddenTracks.Clear();p.LockedTracks.Clear();p.SnapDisabledTracks.Clear();Check(json.Serialize(p)==baseline,"target generation never mutates timeline data");
  Check(TimelineSnapping.Snap(10,new[]{14.0,10.5},1,false)==10.5,"snapping chooses nearest rather than first candidate");Check(TimelineSnapping.Snap(10,new[]{9.0,11},1,false)==9,"equidistant tie retains stable target order");Check(TimelineSnapping.Snap(1.124,new[]{1.0},64,false)==1,"eight-display-pixel threshold scales with zoom");Check(TimelineSnapping.Snap(1.125,new[]{1.0},64,false)==1.125,"exact threshold does not snap");Check(TimelineSnapping.Snap(1.126,new[]{1.0},64,false)==1.126,"outside threshold preserves candidate");Check(TimelineSnapping.Snap(1.01,new[]{1.0},64,true)==1.01,"explicit bypass leaves candidate unchanged");Check(TimelineSnapping.Snap(2,new double[0],64,false)==2,"empty target list preserves candidate");SnapReject(()=>TimelineSnapping.Snap(double.NaN,new[]{0.0},1,false),"nonfinite snap position rejected");SnapReject(()=>TimelineSnapping.Snap(0,new[]{double.PositiveInfinity},1,false),"nonfinite snap target rejected");SnapReject(()=>TimelineSnapping.Snap(0,new[]{0.0},0,false),"invalid snap zoom rejected");SnapReject(()=>TimelineSnapping.Targets(null,all,null,null,null),"null snapping project rejected");SnapReject(()=>TimelineSnapping.Targets(p,null,null,null,null),"null snapping options rejected");
  p=Clone(original);TimelineMarkers.Add(p,.5);Reset(editor,p);Set(editor,"zoom",100.0);Call(editor,"Seek",.75);baseline=json.Serialize(P(editor));double head=(double)Field(editor,"head");var before=Preview(preview,P(editor));var exported=Export(P(editor),"snapping-before");var settings=(TimelineSnapOptions)Field(editor,"timelineSnapping");var menu=Tree(editor).OfType<Menu>().SelectMany(m=>m.Items.OfType<MenuItem>()).First(m=>(string)m.Header=="_View").Items.OfType<MenuItem>().First(m=>(string)m.Header=="Timeline Snapping");Check(menu.Items.Count==3&&menu.Items.OfType<MenuItem>().All(m=>m.IsCheckable&&m.IsChecked),"View menu exposes three functional enabled target options");var markers=menu.Items.OfType<MenuItem>().First(m=>(string)m.Header=="Markers");var edges=menu.Items.OfType<MenuItem>().First(m=>(string)m.Header=="Media Edges");var playhead=menu.Items.OfType<MenuItem>().First(m=>(string)m.Header=="Playhead");
  Check((double)Call(editor,"SnapPlayheadTime",.52)==.5,"playhead movement targets markers when enabled");markers.IsChecked=false;markers.RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));Check(!settings.Markers&&(double)Call(editor,"SnapPlayheadTime",.52)==.52,"actual Markers menu disables marker snapping");Check((double)Call(editor,"SnapPlayheadTime",.98)==1,"playhead movement targets clip edges");edges.IsChecked=false;edges.RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));Check(!settings.MediaEdges&&(double)Call(editor,"SnapPlayheadTime",.98)==.98,"actual Media Edges menu disables edge snapping");Check((double)Call(editor,"SnapMarkerCreation",.77)==.75,"marker creation snaps to enabled playhead");Check((double)Call(editor,"SnapMarkerTime",.77,P(editor).Markers[0].Id)==.75,"marker movement snaps to enabled playhead");playhead.IsChecked=false;playhead.RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));Check(!settings.Playhead&&(double)Call(editor,"SnapMarkerCreation",.77)==.77&&(double)Call(editor,"SnapMarkerTime",.77,P(editor).Markers[0].Id)==.77,"actual Playhead menu disables marker and creation targets");Check(json.Serialize(P(editor))==baseline&&Undos(editor)==0&&!(bool)Field(editor,"dirty")&&(double)Field(editor,"head")==head,"snapping options preserve project dirty history and head");Call(editor,"Refresh");Check(!settings.Markers&&!settings.MediaEdges&&!settings.Playhead,"settings survive editor refresh");Set(editor,"project",Clone(p));Call(editor,"Refresh");Check(object.ReferenceEquals(settings,Field(editor,"timelineSnapping"))&&!settings.Markers&&!settings.MediaEdges&&!settings.Playhead,"session settings survive project instance changes");
  markers.IsChecked=edges.IsChecked=playhead.IsChecked=true;markers.RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));edges.RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));playhead.RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));var group=P(editor).Clips.ToList();Check((double)Call(editor,"SnapClipStart",.52,group)==.5,"clip/group movement uses enabled marker target");Check((double)Call(editor,"SnapClipStart",.98,group)==.98,"clip/group movement excludes all moving group edges");P(editor).SnapDisabledTracks.Add(0);Check((double)Call(editor,"SnapClipStart",.52,group)==.52,"source-track snapping flag bypasses group movement snapping");P(editor).SnapDisabledTracks.Clear();Check((double)Call(editor,"SnapPlayheadTime",.77)==.77,"playhead movement cannot snap to its own previous time");
  Check(Preview(preview,P(editor)).SequenceEqual(before)&&Export(P(editor),"snapping-after").SequenceEqual(exported),"session snapping settings leave preview and decoded export unchanged");string save=Path.Combine(root,"snapping.tasiaproj");Engine.Save(P(editor),save);Check(json.Serialize(Engine.Load(save))==baseline,"settings do not change saved/reopened project data");playhead.IsChecked=false;playhead.RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));Call(editor,"AddMarkerAt",.9);Call(editor,"Undo");Check(!settings.Playhead,"session snapping option survives undo");Call(editor,"Redo");Check(!settings.Playhead,"session snapping option survives redo");playhead.IsChecked=true;playhead.RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));Reset(editor,original);
 }
}
